#nullable enable

class C
{
    (C, C) M0(object obj) => (this, this);

    void M1(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is (_, _)
            ? x.ToString()
            : y.ToString(); // 1
    }

    void M2(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is not null
            ? x.ToString()
            : y.ToString(); // 2
    }

    void M3(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is (not null, null)
            ? x.ToString()
            : y.ToString(); // 3
    }

    void M4(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is null
            ? x.ToString() // 4
            : y.ToString();
    }

    void M5(C? c)
    {
        int x, y;
        _ = (c?.M0(x = 0), c?.M0(y = 0)) is (not null, not null)
            ? x.ToString() // 5
            : y.ToString(); // 6
    }
}

